-- =========================================================================
-- SEED DATA PERIODE PENILAIAN LENGKAP (100% SELESAI)
-- Dinas Pekerjaan Umum Bina Marga Provinsi Jawa Timur
-- =========================================================================
--
-- Tujuan:
--   Membuat satu periode penilaian lengkap ("Penilaian Tahunan 2025",
--   kode PRD-2025-LENGKAP) di mana seluruh 480 pegawai telah dipetakan
--   secara merata (6.733 penugasan 360 derajat), seluruh penilai telah
--   mengisi jawaban + komentar masukan, berstatus 'selesai' (100%), serta
--   nilai akhir & predikat tersimpan pada tabel hasil_penilaian & audit_log.
--
-- Prasyarat Import:
--   1. database/schema.sql
--   2. Data pegawai (ID 1-480) sudah terisi pada tabel `pegawai`
--   3. database/seed_periode_lengkap.sql  (file ini)
--
-- Cara Import (CLI):
--   mysql -u root -p penilaian360 < database/seed_periode_lengkap.sql
-- =========================================================================

USE penilaian360;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;

-- 1. User Super Admin sebagai pembuat / penghitung resmi
SET @creator_id = IFNULL(
    (SELECT id FROM users WHERE role = 'super_admin' ORDER BY id ASC LIMIT 1),
    1
);

-- 2. Buat ulang periode 'PRD-2025-LENGKAP' secara idempoten (cascade mapping/jawaban/hasil)
DELETE FROM periode_penilaian WHERE kode_periode = 'PRD-2025-LENGKAP';

     tanggal_mulai, tanggal_selesai, tanggal_mulai_pengisian, tanggal_akhir_pengisian,
     status, keterangan, created_by)
VALUES
    ('PRD-2025-LENGKAP', 'Penilaian Tahunan 2025', 2025, 'tahunan', 'tahunan', 'semua', NULL,
     '2025-01-01', '2025-12-31', '2025-12-01 08:00:00', '2025-12-20 23:59:59',
     'ditutup',
     'Periode penilaian kinerja 360 derajat lengkap (seluruh pegawai telah menyelesaikan penilaian).',
     @creator_id);

SET @periode_id = LAST_INSERT_ID();

