-- =========================================================================
-- 4. JAWABAN PENILAIAN (Formula deterministik mengikuti profil skor 4 tier,
--    penyesuaian relasi, dan variasi antar butir tanpa straight-lining)
-- =========================================================================
SELECT
    calc.mapping_id,
    calc.pertanyaan_id,
    CASE
        -- Pencegahan straight-lining jika seluruh butir di satu tugas bernilai sama
        WHEN calc.pertanyaan_id = calc.first_q_id AND calc.skor_base = calc.max_s THEN calc.max_s - 1
        ELSE calc.skor_base
    END AS skor
FROM (
    SELECT
        m.id AS mapping_id,
        q.id AS pertanyaan_id,
        q.min_s,
        q.max_s,
        (
            SELECT MIN(qf.id)
            FROM pertanyaan_penilaian qf
            WHERE qf.status = 'aktif'
              AND (TRIM(IFNULL(qf.target_relasi, '')) = '' OR FIND_IN_SET(m.jenis_relasi, REPLACE(qf.target_relasi, ' ', '')) > 0)
        ) AS first_q_id,
        LEAST(
            q.max_s,
            GREATEST(
                q.min_s,
                ROUND(
                    (
                        CASE
                            WHEN MOD((m.pegawai_dinilai_id * 2654435761) & 2147483647, 100) < 25 THEN 4.70
                            WHEN MOD((m.pegawai_dinilai_id * 2654435761) & 2147483647, 100) < 80 THEN 4.15
                            WHEN MOD((m.pegawai_dinilai_id * 2654435761) & 2147483647, 100) < 96 THEN 3.45
                            ELSE 2.85
                        END
                        + CASE
                            WHEN m.jenis_relasi = 'diri'   THEN  0.15
                            WHEN m.jenis_relasi = 'atasan' THEN -0.05
                            ELSE 0.00
                        END
                    )
                    + (
                        (
                            MOD(
                                ((m.pegawai_dinilai_id * 1103515245 + m.pegawai_penilai_id * 12345) & 2147483647)
                                + q.id * 7919,
                                100
                            ) / 100.0
                        ) - 0.5
                    ) * 1.3
                )
            )
        ) AS skor_base
    FROM mapping_penilai m
    JOIN (
        SELECT
            id,
            target_relasi,
            GREATEST(1, skor_min) AS min_s,
            GREATEST(GREATEST(1, skor_min), skor_max) AS max_s
        FROM pertanyaan_penilaian
        WHERE status = 'aktif'
    ) q ON (
        TRIM(IFNULL(q.target_relasi, '')) = ''
        OR FIND_IN_SET(m.jenis_relasi, REPLACE(q.target_relasi, ' ', '')) > 0
    )
    WHERE m.periode_id = @periode_id
) calc;

-- Jaminan akhir nol straight-lining pada penugasan >= 3 butir pertanyaan
UPDATE jawaban_penilaian j
JOIN (
    SELECT
        m.id AS mapping_id,
        MIN(j2.pertanyaan_id) AS first_q_id,
        MIN(j2.skor) AS uniform_skor
    FROM mapping_penilai m
    JOIN jawaban_penilaian j2 ON j2.mapping_id = m.id
    WHERE m.periode_id = @periode_id
    GROUP BY m.id
    HAVING COUNT(*) >= 3 AND COUNT(DISTINCT j2.skor) = 1
) sl ON sl.mapping_id = j.mapping_id AND sl.first_q_id = j.pertanyaan_id
SET j.skor = IF(sl.uniform_skor < 5, sl.uniform_skor + 1, sl.uniform_skor - 1);

-- =========================================================================
-- 5. HASIL PENILAIAN (Kalkulasi resmi mengikuti results_calculator.php
--    termasuk pembedaan Struktural vs Pelaksana & dynamic re-weighting)
-- =========================================================================
SET @b_atasan  = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'bobot_atasan'), 50.0);
SET @b_rekan   = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'bobot_rekan'), 15.0);
SET @b_bawahan = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'bobot_bawahan'), 25.0);
SET @b_diri    = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'bobot_diri_sendiri'), 10.0);

SET @bp_atasan = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'bobot_pelaksana_atasan'), 50.0);
SET @bp_rekan  = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'bobot_pelaksana_rekan'), 40.0);
SET @bp_diri   = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'bobot_pelaksana_diri_sendiri'), @b_diri);

SET @amb_sb = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'ambang_predikat_sangat_baik'), 91.0);
SET @amb_b  = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'ambang_predikat_baik'), 76.0);
SET @amb_c  = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'ambang_predikat_cukup'), 61.0);
SET @amb_k  = IFNULL((SELECT CAST(config_value AS DECIMAL(8,4)) FROM konfigurasi_sistem WHERE config_key = 'ambang_predikat_kurang'), 51.0);

     nilai_akhir, predikat, tanggal_hitung, dihitung_oleh, catatan)
SELECT
    @periode_id,
    fin.pegawai_id,
    fin.nd,
    fin.na,
    fin.nr,
    fin.nb,
    fin.nilai_akhir,
    CASE
        WHEN fin.nilai_akhir IS NULL THEN NULL
        WHEN fin.nilai_akhir >= @amb_sb THEN 'Sangat Baik'
        WHEN fin.nilai_akhir >= @amb_b  THEN 'Baik'
        WHEN fin.nilai_akhir >= @amb_c  THEN 'Cukup'
        WHEN fin.nilai_akhir >= @amb_k  THEN 'Kurang'
        ELSE 'Sangat Kurang'
    END AS predikat,
    '2025-12-21 09:00:00',
    @creator_id,
    'Hasil kalkulasi otomatis periode Penilaian Tahunan 2025'
FROM (
    SELECT
        w.pegawai_id,
        w.nd,
        w.na,
        w.nr,
        w.nb,
        ROUND(
            (
                IF(w.na IS NOT NULL AND w.w_atasan  > 0, w.na * w.w_atasan,  0)
              + IF(w.nr IS NOT NULL AND w.w_rekan   > 0, w.nr * w.w_rekan,   0)
              + IF(w.nb IS NOT NULL AND w.w_bawahan > 0, w.nb * w.w_bawahan, 0)
              + IF(w.nd IS NOT NULL AND w.w_diri    > 0, w.nd * w.w_diri,    0)
            ) / NULLIF(w.w_atasan + w.w_rekan + w.w_bawahan + w.w_diri, 0),
            2
        ) AS nilai_akhir
    FROM (
        SELECT
            emp.pegawai_id,
            emp.nd,
            emp.na,
            emp.nr,
            emp.nb,
            CASE
                WHEN emp.has_bawahan = 1 THEN
                    CASE
                        WHEN emp.na IS NOT NULL AND emp.nr IS NOT NULL AND emp.nb IS NOT NULL THEN @b_atasan
                        WHEN emp.na IS NOT NULL AND emp.nr IS NULL     AND emp.nb IS NOT NULL THEN ROUND(emp.sisa_str * 0.7, 1)
                        WHEN emp.na IS NOT NULL AND emp.nr IS NOT NULL AND emp.nb IS NULL     THEN ROUND(emp.sisa_str * 0.8, 1)
                        WHEN emp.na IS NOT NULL AND emp.nr IS NULL     AND emp.nb IS NULL     THEN emp.sisa_str
                        ELSE 0.0
                    END
                ELSE
                    CASE
                        WHEN emp.na IS NOT NULL AND emp.nr IS NOT NULL THEN @bp_atasan
                        WHEN emp.na IS NOT NULL AND emp.nr IS NULL     THEN emp.sisa_pel
                        ELSE 0.0
                    END
            END AS w_atasan,
            CASE
                WHEN emp.has_bawahan = 1 THEN
                    CASE
                        WHEN emp.na IS NOT NULL AND emp.nr IS NOT NULL AND emp.nb IS NOT NULL THEN @b_rekan
                        WHEN emp.na IS NULL     AND emp.nr IS NOT NULL AND emp.nb IS NOT NULL THEN ROUND(emp.sisa_str * 0.4, 1)
                        WHEN emp.na IS NOT NULL AND emp.nr IS NOT NULL AND emp.nb IS NULL     THEN ROUND(emp.sisa_str * 0.2, 1)
                        WHEN emp.na IS NULL     AND emp.nr IS NOT NULL AND emp.nb IS NULL     THEN emp.sisa_str
                        ELSE 0.0
                    END
                ELSE
                    CASE
                        WHEN emp.na IS NOT NULL AND emp.nr IS NOT NULL THEN @bp_rekan
                        WHEN emp.na IS NULL     AND emp.nr IS NOT NULL THEN emp.sisa_pel
                        ELSE 0.0
                    END
            END AS w_rekan,
            CASE
                WHEN emp.has_bawahan = 1 THEN
                    CASE
                        WHEN emp.na IS NOT NULL AND emp.nr IS NOT NULL AND emp.nb IS NOT NULL THEN @b_bawahan
                        WHEN emp.na IS NULL     AND emp.nr IS NOT NULL AND emp.nb IS NOT NULL THEN ROUND(emp.sisa_str * 0.6, 1)
                        WHEN emp.na IS NOT NULL AND emp.nr IS NULL     AND emp.nb IS NOT NULL THEN ROUND(emp.sisa_str * 0.3, 1)
                        WHEN emp.na IS NULL     AND emp.nr IS NULL     AND emp.nb IS NOT NULL THEN emp.sisa_str
                        ELSE 0.0
                    END
                ELSE 0.0
            END AS w_bawahan,
            CASE
                WHEN emp.has_bawahan = 1 THEN IF(emp.nd IS NOT NULL AND @b_diri  > 0, @b_diri,  0.0)
                ELSE                          IF(emp.nd IS NOT NULL AND @bp_diri > 0, @bp_diri, 0.0)
            END AS w_diri
        FROM (
            SELECT
                ms.pegawai_id,
                ROUND(AVG(CASE WHEN ms.jenis_relasi = 'diri'    THEN ms.skor_map END), 2) AS nd,
                ROUND(AVG(CASE WHEN ms.jenis_relasi = 'atasan'  THEN ms.skor_map END), 2) AS na,
                ROUND(AVG(CASE WHEN ms.jenis_relasi = 'rekan'   THEN ms.skor_map END), 2) AS nr,
                ROUND(AVG(CASE WHEN ms.jenis_relasi = 'bawahan' THEN ms.skor_map END), 2) AS nb,
                GREATEST(0.0, 100.0 - IF(ROUND(AVG(CASE WHEN ms.jenis_relasi = 'diri' THEN ms.skor_map END), 2) IS NOT NULL AND @b_diri  > 0, @b_diri,  0.0)) AS sisa_str,
                GREATEST(0.0, 100.0 - IF(ROUND(AVG(CASE WHEN ms.jenis_relasi = 'diri' THEN ms.skor_map END), 2) IS NOT NULL AND @bp_diri > 0, @bp_diri, 0.0)) AS sisa_pel,
                IF(
                    EXISTS(SELECT 1 FROM mapping_penilai mb WHERE mb.periode_id = @periode_id AND mb.pegawai_dinilai_id = ms.pegawai_id AND mb.jenis_relasi = 'bawahan')
                    OR EXISTS(SELECT 1 FROM pegawai p WHERE p.atasan_langsung_id = ms.pegawai_id AND p.status_aktif = 'aktif'),
                    1, 0
                ) AS has_bawahan
            FROM (
                SELECT
                    m.id AS mapping_id,
                    m.pegawai_dinilai_id AS pegawai_id,
                    m.jenis_relasi,
                    SUM((j.skor / GREATEST(1, q.skor_max)) * 100.0 * IF(q.bobot > 0, q.bobot, 1.0))
                        / NULLIF(SUM(IF(q.bobot > 0, q.bobot, 1.0)), 0) AS skor_map
                FROM mapping_penilai m
                JOIN jawaban_penilaian j ON j.mapping_id = m.id
                JOIN pertanyaan_penilaian q ON q.id = j.pertanyaan_id
                WHERE m.periode_id = @periode_id
                  AND m.status = 'selesai'
                GROUP BY m.id, m.pegawai_dinilai_id, m.jenis_relasi
            ) ms
            GROUP BY ms.pegawai_id
        ) emp
    ) w
) fin
ON DUPLICATE KEY UPDATE
    nilai_diri     = VALUES(nilai_diri),
    nilai_atasan   = VALUES(nilai_atasan),
    nilai_rekan    = VALUES(nilai_rekan),
    nilai_bawahan  = VALUES(nilai_bawahan),
    nilai_akhir    = VALUES(nilai_akhir),
    predikat       = VALUES(predikat),
    tanggal_hitung = VALUES(tanggal_hitung),
    dihitung_oleh  = VALUES(dihitung_oleh),
    catatan        = VALUES(catatan);

-- =========================================================================
-- 6. AUDIT LOG AKTIVITAS PERIODE LENGKAP
-- =========================================================================
SET @total_mapping = (SELECT COUNT(*) FROM mapping_penilai WHERE periode_id = @periode_id);
SET @total_pegawai_hasil = (SELECT COUNT(*) FROM hasil_penilaian WHERE periode_id = @periode_id);


SET FOREIGN_KEY_CHECKS = 1;

SELECT 'Seed periode lengkap berhasil diimport.' AS status,
       @periode_id                               AS periode_id,
       (SELECT COUNT(*) FROM mapping_penilai   WHERE periode_id = @periode_id) AS total_mapping,
       (SELECT COUNT(*) FROM jawaban_penilaian j JOIN mapping_penilai m ON m.id = j.mapping_id WHERE m.periode_id = @periode_id) AS total_jawaban,
       (SELECT COUNT(*) FROM hasil_penilaian   WHERE periode_id = @periode_id) AS total_hasil;
